-- Real products from Open Food Facts (https://world.openfoodfacts.org, ODbL),
-- looked up by barcode with apps/web/scripts/off-seed-sql.ts and lightly
-- cleaned (OCR noise in ingredient lists, brand spellings).
-- Price and stock are intentionally empty: products only appear in the
-- storefront after staff set a price and stock in Admin > Products.
on conflict (barcode) do update set
  name = excluded.name, brand = excluded.brand, category = excluded.category,
  quantity_label = excluded.quantity_label, description = excluded.description,
  ingredients = excluded.ingredients, nutriscore_grade = excluded.nutriscore_grade,
  image_url = excluded.image_url, source_synced_at = now();
